function RaceMode({room,me,game}:{room:R;me?:P;game:G}){const ref=useRef<HTMLCanvasElement>(null),keys=useRef(new Set<string>());useEffect(()=>{const down=(e:KeyboardEvent)=>{if(['INPUT','TEXTAREA'].includes((e.target as HTMLElement)?.tagName))return;keys.current.add(e.key.toLowerCase())},up=(e:KeyboardEvent)=>keys.current.delete(e.key.toLowerCase());addEventListener('keydown',down);addEventListener('keyup',up);const t=window.setInterval(()=>{let x=0,y=0;if(keys.current.has('w')||keys.current.has('ц')||keys.current.has('arrowup'))y--;if(keys.current.has('s')||keys.current.has('ы')||keys.current.has('arrowdown'))y++;if(keys.current.has('a')||keys.current.has('ф')||keys.current.has('arrowleft'))x--;if(keys.current.has('d')||keys.current.has('в')||keys.current.has('arrowright'))x++;if(x||y)socket.emit('race:move',{x,y})},45);return()=>{removeEventListener('keydown',down);removeEventListener('keyup',up);clearInterval(t)}},[]);useEffect(()=>{const c=ref.current;if(!c)return;const ctx=c.getContext('2d')!,tr=game.track||[];ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#ead9a7';ctx.fillRect(0,0,c.width,c.height);if(tr.length){ctx.lineJoin='round';ctx.lineCap='round';ctx.strokeStyle='#f4f0e7';ctx.lineWidth=174;ctx.beginPath();ctx.moveTo(tr[0].x,tr[0].y);for(const q of tr)ctx.lineTo(q.x,q.y);ctx.stroke();ctx.strokeStyle='#e53b2e';ctx.lineWidth=164;ctx.setLineDash([18,18]);ctx.beginPath();ctx.moveTo(tr[0].x,tr[0].y);for(const q of tr)ctx.lineTo(q.x,q.y);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#c88736';ctx.lineWidth=146;ctx.beginPath();ctx.moveTo(tr[0].x,tr[0].y);for(const q of tr)ctx.lineTo(q.x,q.y);ctx.stroke();ctx.strokeStyle='rgba(255,255,255,.28)';ctx.lineWidth=4;ctx.setLineDash([24,22]);ctx.beginPath();ctx.moveTo(tr[0].x,tr[0].y);for(const q of tr)ctx.lineTo(q.x,q.y);ctx.stroke();ctx.setLineDash([]);for(let i=1;i<tr.length-1;i++){const q=tr[i];ctx.fillStyle='rgba(255,255,255,.14)';ctx.beginPath();ctx.arc(q.x,q.y,10,0,Math.PI*2);ctx.fill()}for(const q of tr.filter(q=>q.obstacle)){ctx.font='32px sans-serif';ctx.fillText('🪨',q.x-16,q.y+12)}const s=tr[0];ctx.strokeStyle='#111';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(s.x-55,s.y-18);ctx.lineTo(s.x+55,s.y-18);ctx.moveTo(s.x-55,s.y+18);ctx.lineTo(s.x+55,s.y+18);ctx.stroke()}for(const pl of room.players){const q=game.racers?.[pl.id];if(!q)continue;ctx.font='30px sans-serif';ctx.fillText(pl.id===me?.id?'🚙':'🚗',q.x-15,q.y+11);ctx.font='bold 12px Arial';ctx.fillStyle='#111';ctx.fillText(`${pl.name} · ${Math.min(q.checkpoint||0,Math.max(0,(game.track?.length||1)-1))}/${Math.max(1,(game.track?.length||2)-1)}`,q.x-35,q.y-20)}},[room,game,me]);const count=Math.max(0,Math.ceil(((game.countdownEndsAt||0)-Date.now())/1000)),left=Math.max(0,Math.ceil(((game.endsAt||Date.now())-Date.now())/1000));if(game.phase==='results'){const sorted=room.players.slice().sort((a,b)=>{const A=game.racers?.[a.id],B=game.racers?.[b.id];if(A?.finishedAt&&B?.finishedAt)return A.finishedAt-B.finishedAt;if(A?.finishedAt)return-1;if(B?.finishedAt)return 1;return(B?.checkpoint||0)-(A?.checkpoint||0)});return <main className="arcade"><div className="panel arcadeResults"><h1>ГОНКА ОКОНЧЕНА</h1>{sorted.map((p,i)=><div className="place" key={p.id}><b>#{i+1}</b><span>{p.name}</span><strong>{game.racers?.[p.id]?.finishedAt?'ФИНИШ':`КП ${game.racers?.[p.id]?.checkpoint||0}`}</strong></div>)}{me?.host&&<button className="primary" onClick={()=>socket.emit('game:lobby')}>В КОМНАТУ</button>}</div></main>}return <main className="arcade raceMode"><header><b>ЕБЛАНГЕЙМ / ГОНКИ</b><span>{count>0?`СТАРТ: ${count}`:`ОСТАЛОСЬ: ${left}`}</span>{me?.host&&<button onClick={()=>socket.emit('game:lobby')}>В КОМНАТУ</button>}</header><canvas ref={ref} width={1000} height={620}/><MobilePad onMove={(x,y)=>socket.emit('race:move',{x,y})}/><p className="arcadeHelp">WASD/стрелки. Ехать можно только по коричневой дороге. Контрольные точки идут строго по порядку, поэтому срезать трассу нельзя.</p></main>}

